#include "stdlib/blas/ext/base/svander.h"
#include "stdlib/blas/ext/base/sfill.h"
#include "stdlib/ndarray/base/assert/is_row_major.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"
#include <stdint.h>

/**
* Generates a single-precision floating-point Vandermonde matrix.
*
* @param order   storage layout
* @param M       number of rows in the matrix `Out`
* @param N       number of columns in the matrix `Out`
* @param mode    specifies whether powers are increasing (1) or decreasing (-1)
* @param X       input vector
* @param strideX stride length for `X`
* @param Out     output matrix
* @param LDO     stride length for the leading dimension of `Out`
*/
void API_SUFFIX(stdlib_strided_svander)( const CBLAS_LAYOUT order, const CBLAS_INT M, const CBLAS_INT N, const float mode, const float *X, const CBLAS_INT strideX, float *Out, const CBLAS_INT LDO ) {
	CBLAS_INT sa1;
	CBLAS_INT sa2;
	CBLAS_INT ox;

	ox = stdlib_strided_stride2offset( M, strideX );
	if ( order == CblasColMajor ) {
		sa1 = 1;
		sa2 = LDO;
	} else { // order == CblasRowMajor
		sa1 = LDO;
		sa2 = 1;
	}
	API_SUFFIX(stdlib_strided_svander_ndarray)( M, N, mode, X, strideX, ox, Out, sa1, sa2, 0 );
}

/**
* Generates a single-precision floating-point Vandermonde matrix using alternative indexing semantics.
*
* @param M          number of rows in the matrix `Out`
* @param N          number of columns in the matrix `Out`
* @param mode       specifies whether powers are increasing (1) or decreasing (-1)
* @param X          input vector
* @param strideX    stride length for `X`
* @param offsetX    starting index for `X`
* @param Out        output matrix
* @param strideOut1 stride length for the first dimension of `Out`
* @param strideOut2 stride length for the second dimension of `Out`
* @param offsetOut  starting index for `Out`
*/
void API_SUFFIX(stdlib_strided_svander_ndarray)( const CBLAS_INT M, const CBLAS_INT N, const float mode, const float *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, float *Out, const CBLAS_INT strideOut1, const CBLAS_INT strideOut2, const CBLAS_INT offsetOut ) {
	int64_t sa[ 2 ];
	CBLAS_INT do0;
	CBLAS_INT do1;
	CBLAS_INT rm;
	CBLAS_INT S0;
	CBLAS_INT S1;
	CBLAS_INT sx;
	CBLAS_INT io;
	CBLAS_INT ix;
	CBLAS_INT i0;
	CBLAS_INT i1;

	if ( M == 0 || N == 0 ) {
		return;
	}

	// Determine whether the matrix is row-major...
	sa[ 0 ] = strideOut1;
	sa[ 1 ] = strideOut2;
	if ( stdlib_ndarray_is_row_major( 2, sa ) ) {
		rm = 1;
	} else {
		rm = 0;
	}

	// Extract loop variables for loop interchange...
	if ( rm ) {
		S0 = N;
		S1 = M;
		do0 = strideOut2;
		do1 = strideOut1 - ( S0 * strideOut2 );
	} else {
		S0 = M;
		S1 = N;
		do0 = strideOut1;
		do1 = strideOut2 - ( S0 * strideOut1 );
	}
	sx = strideX;
	io = offsetOut;

	if ( rm ) {
		ix = offsetX;
		for ( i1 = 0; i1 < S1; i1++ ) {
			if ( mode > 0 ) {
				// Increasing: x^0, x^1, ..., x^(N-1)
				Out[ io ] = 1.0f;
				io += do0;
				for ( i0 = 1; i0 < S0; i0++ ) {
					Out[ io ] = Out[ io - do0 ] * X[ ix ];
					io += do0;
				}
			} else {
				// Decreasing: x^(N-1), x^(N-2), ..., x^0
				Out[ io + ( ( S0-1 ) * do0 ) ] = 1.0f;
				for ( i0 = S0 - 2; i0 >= 0; i0-- ) {
					Out[ io + ( i0*do0 ) ] = Out[ io + ( (i0+1)*do0 ) ] * X[ ix ];
				}
				io += S0 * do0;
			}
			ix += sx;
			io += do1;
		}
	} else if ( mode > 0 ) {
		// Increasing: column j contains x^j
		API_SUFFIX(stdlib_strided_sfill_ndarray)( S0, 1.0f, Out, do0, io );
		io += ( S0 * do0 ) + do1;
		for ( i1 = 1; i1 < S1; i1++ ) {
			ix = offsetX;
			for ( i0 = 0; i0 < S0; i0++ ) {
				Out[ io ] = Out[ io - strideOut2 ] * X[ ix ];
				ix += sx;
				io += do0;
			}
			io += do1;
		}
	} else {
		// Decreasing: column 0 contains x^(N-1), last column all ones
		API_SUFFIX(stdlib_strided_sfill_ndarray)( S0, 1.0f, Out, do0, offsetOut + ( ( S1-1 ) * strideOut2 ) );
		for ( i1 = S1 - 2; i1 >= 0; i1-- ) {
			io = offsetOut + ( i1 * strideOut2 );
			ix = offsetX;
			for ( i0 = 0; i0 < S0; i0++ ) {
				Out[ io ] = Out[ io + strideOut2 ] * X[ ix ];
				ix += sx;
				io += do0;
			}
		}
	}
}
